import os
import time
import signal
import tempfile
import subprocess
from threading import Event
from abc import ABCMeta, abstractmethod

from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.utils import exception_causes
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils.timer_guard import TimerGuard

logger = custom_logger('Tshark')


ADDITIONAL_WAIT_TIME_FOR_TSHARK_TO_BE_READY = 1


class TsharkError(LibraryError):
    def __init__(self, msg):
        super(TsharkError, self).__init__(exception_causes.CALL_SEQUENCE_ERROR, msg)


class TsharkTimeoutError(LibraryError):
    def __init__(self, msg):
        super(TsharkTimeoutError, self).__init__(exception_causes.TIMEOUT, msg)


class TsharkTimeoutPolicy(object):
    __metaclass__ = ABCMeta

    @property
    def msg(self):
        return 'Tshark did not start in given time'

    @abstractmethod
    def run(self):
        pass


class IgnoreTimeout(TsharkTimeoutPolicy):
    def run(self):
        logger.error(self.msg)


class RaiseTimeoutError(TsharkTimeoutPolicy):
    def run(self):
        raise TsharkTimeoutError(self.msg)


class PathProvider(object):
    def __init__(self):
        self._created_temp_files = []
        self._file_name_index = 1

    def cleanup(self):
        for f in self._created_temp_files:
            if os.path.exists(f):
                os.remove(f)

    def get_path(self, path):
        return path if path else self.get_temp_file()

    def get_temp_file(self):
        f = tempfile.mkstemp()[self._file_name_index]
        self._created_temp_files.append(f)
        return f


class StreamHandlers(object):
    def __init__(self):
        self._stdout_path = None
        self._stderr_path = None
        self._stdout_write = None
        self._stderr_write = None
        self._path_provider = PathProvider()
        self._read_only_handlers = []

    @property
    def stdout_read(self):
        return self._create_read_only_handler(self._stdout_path)

    @property
    def stdout_write(self):
        return self._stdout_write

    @property
    def stderr_read(self):
        return self._create_read_only_handler(self._stderr_path)

    @property
    def stderr_write(self):
        return self._stderr_write

    def create(self, stdout, stderr):
        self._stdout_path = self._path_provider.get_path(stdout)
        self._stderr_path = self._path_provider.get_path(stderr)
        self._stdout_write = open(self._stdout_path, 'wb')
        self._stderr_write = open(self._stderr_path, 'wb')

    def close(self):
        self._stdout_write.close()
        self._stderr_write.close()
        self._close_read_only_handlers()
        self._path_provider.cleanup()

    def _create_read_only_handler(self, handler_path):
        h = open(handler_path, 'rb')
        self._read_only_handlers.append(h)
        return h

    def _close_read_only_handlers(self):
        for h in self._read_only_handlers:
            if not h.closed:
                h.close()


class Tshark(object):
    def __init__(self):
        self._cmd = ['tshark']
        self._process = None
        self._handlers = StreamHandlers()
        self._capture_readiness_handler = None
        self._capturing_ready_string = 'Capturing'

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.stop()

    def set_interface(self, interface):
        self._cmd.extend(['-i', interface])

    def set_input_file(self, input_path):
        self._cmd.extend(['-r', input_path])

    def set_output_file(self, output_file):
        self._cmd.extend(['-w', output_file])

    def set_filter(self, tshark_filter):
        self._cmd.extend(['-Y', tshark_filter])

    def set_capture_filter(self, capture_filter):
        self._cmd.extend(['-f', capture_filter])

    def set_capture_snaplen(self, capture_snaplen):
        self._cmd.extend(['-s', capture_snaplen])

    def set_chunk_size(self, chunk_size):
        self._cmd.extend(['-b', 'filesize:{}'.format(chunk_size)])

    @typed(megabytes=str)
    def set_buffer_size(self, megabytes):
        self._cmd.extend(['-B', megabytes])

    def set_text_output_format(self, output_format):
        self._cmd.extend(['-T', output_format])

    def set_field_to_print(self, field):
        self._cmd.extend(['-e', field])

    def flush_output_after_each_packet(self):
        self._cmd.extend(['-l'])

    @property
    def cmd(self):
        return self._cmd

    @property
    def stdout(self):
        return self._handlers.stdout_read

    @property
    def stderr(self):
        return self._handlers.stderr_read

    def start(self, stdout=None, stderr=None):
        self._assert_process_not_in_started_state()

        self._handlers.create(stdout, stderr)
        self._process = subprocess.Popen(self._cmd,
                                         preexec_fn=os.setsid,
                                         stdout=self._handlers.stdout_write,
                                         stderr=self._handlers.stderr_write)
        self._capture_readiness_handler = self._handlers.stderr_read
        logger.debug('Tshark started')

    def _assert_process_not_in_started_state(self):
        if self._process is not None:
            raise TsharkError('Tshark already started.')

    def run_until_completion(self):
        return subprocess.check_output(self._cmd, stderr=subprocess.STDOUT)

    def stop(self, process_termination_timeout=2.0):
        if self._process is None:
            return
        if self._process.returncode is not None:
            return

        with TimerGuard(timeout_handler=self._kill, seconds=process_termination_timeout):
            self._terminate_process()
            self._wait_until_complete()

        self._handlers.close()
        logger.debug('Tshark stopped')

    def _terminate_process(self):
        os.killpg(os.getpgid(self._process.pid), signal.SIGTERM)

    def _wait_until_complete(self):
        self._process.wait()
        return self._process.returncode

    def _kill(self):
        self._process.kill()

    def wait_for_capturing_started(self, timeout=8.0, timeout_handling_policy=IgnoreTimeout()):
        logger.debug('Waiting for tshark being ready for capturing. Timeout={}'.format(timeout))
        self._assert_process_is_in_started_state()

        timeout_event = Event()
        with TimerGuard(timeout_handler=timeout_event.set, seconds=timeout):
            while not (timeout_event.is_set() or self._is_capturing_ready()):
                time.sleep(0.1)

        if timeout_event.is_set():
            timeout_handling_policy.run()

        time.sleep(ADDITIONAL_WAIT_TIME_FOR_TSHARK_TO_BE_READY)
        logger.debug('Waiting for tshark being ready finished')

    def _assert_process_is_in_started_state(self):
        if self._process is None:
            raise TsharkError('wait_for_capturing_started called before start')
        if isinstance(self._process.returncode, int):
            raise TsharkError('wait_for_capturing_started called when process has been stopped')

    def _is_capturing_ready(self):
        return self._capturing_ready_string in self._capture_readiness_handler.readline().decode('utf-8')
